const main=document.querySelector('main');
const KEY='five-assessment-v1', PREF='five-preferences-v1';
let language=navigator.language.toLowerCase().startsWith('no')||navigator.language.toLowerCase().startsWith('nb')||navigator.language.toLowerCase().startsWith('nn')?'no':'en';
let country=language==='no'?'NO':'US';
