const order=['O','C','E','A','N'];
const anchors=()=>[tr('Very inaccurate','Svært unøyaktig'),tr('Moderately inaccurate','Ganske unøyaktig'),tr('Neither accurate nor inaccurate','Verken nøyaktig eller unøyaktig'),tr('Moderately accurate','Ganske nøyaktig'),tr('Very accurate','Svært nøyaktig')];
