// Only when the facets spread widely: one line above the facet list, since the cards below show every bar and text.
function patternHtml(d){return d.pattern.mixed?`<p class="facet-pattern d-pattern-note">${esc(d.pattern.text)}</p>`:'';}
function traitHead(d){const [infoBtn,infoPop]=hasPct(d)?pctInfoParts(true):['',''],full=name(d),m=full.match(/^(.*?)\s*(\(.*\))$/),art=d.code==='O'?'trait-O.webp':`facets/head-${d.code}.webp`;return `<header class="d-trait-head d-trait-band d-trait-band-${d.code}"><div class="d-trait-head-text">${demo?`<p class="eyebrow">${tr('Example profile','Eksempelprofil')}</p>`:''}<h3 class="d-trait-title">${esc(m?m[1]:full)}${m?`<span class="d-trait-alt">${esc(m[2])}</span>`:''}</h3><p class="d-trait-score"><span class="d-chip d-chip-${d.band}">${bandShort(d.band)}</span> ${esc(scoreText(d))}${infoBtn}</p>${infoPop}<div class="d-trait-head-bar">${miniBar(d,traitColors[d.code])}<div class="d-scale-ends"><span>${tr('Lower','Lavere')}</span><span>${tr('Higher','Høyere')}</span></div></div></div><img class="d-trait-band-art${d.code==='O'?' d-trait-band-panel':''}" src="assets/design/${art}" alt="" aria-hidden="true"></header>`;}
function contextHtml(d,id,open){
  const c=contextCard(d,id,language,reportFigure),pid=`ctx-${id}-${d.code}`;
  const full=name(d),m=full.match(/^(.*?)\s*(\(.*\))$/),short=m?m[1]:full;
  const parts=c.text.match(/^(.+?[.!?])\s+(.+)$/s),head=parts?parts[1]:c.text,rest=parts?parts[2]:'';
  const sw=c.good.length?`<details class="d-ctx-more"><summary>${tr('Read more about this','Les mer om dette')}<span class="d-ctx-more-plus" aria-hidden="true"></span></summary><div class="d-sw"><div class="d-sw-col is-good"><h5>${tr('Strengths','Styrker')}</h5><ul>${c.good.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="d-sw-col is-hard"><h5>${tr('Weaknesses','Svakheter')}</h5><ul>${c.hard.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></details>`:'';
  return `<article class="d-ctx-card${open?' is-open':''}" data-rule="${c.ruleId}" data-code="${d.code}"><h3 class="d-ctx-h"><button type="button" class="d-ctx-toggle" aria-expanded="${open}" aria-controls="${pid}"><span class="d-ctx-art${c.art.includes('/')?' is-scene':''}"><img src="assets/design/context/${c.art}.webp" data-ctx-art="${d.code}|${id}|${c.level}|${c.variant}" alt=""></span><span class="d-ctx-text"><span class="d-ctx-name">${esc(short)}${m?`<span class="d-trait-alt">${esc(m[2])}</span>`:''}<span class="d-chip d-chip-${d.band}">${levelShort(c.level)}</span></span><span class="d-ctx-quote">${esc(c.quote)}</span></span><span class="d-ctx-plus" aria-hidden="true"></span></button></h3></article><div class="d-ctx-panel" id="${pid}" role="region" aria-label="${esc(short)}"${open?'':' hidden'}><div class="d-ctx-main"><p class="d-ctx-eyebrow">${esc(short)} ${id==='work'?tr('at work','i arbeidet'):tr('in everyday life','i hverdagen')}</p><h4>${esc(head)}</h4>${rest?`<p>${esc(rest)}</p>`:''}${sw}</div><div class="d-ctx-try"><span>${tr('Try','Prøv')}</span><p>${esc(c.try)}</p></div></div>`;
}
function normNote(){
  if(!report.norms)return `<p class="d-norm-note d-footnote">${tr('Percentiles appear here once the US reference data is added. Until then, each bar shows where your average sits on the 1–5 answer scale; it is not a comparison with other people.','Persentiler vises her når de amerikanske referansedataene er lagt inn. Til da viser hver stolpe hvor gjennomsnittet ditt ligger på svarskalaen fra 1 til 5; den er ikke en sammenligning med andre.')}</p>`;
  const n=new Intl.NumberFormat(language==='no'?'nb-NO':'en-US').format(report.norms.n);
  return `<p class="d-norm-note d-footnote">${tr(`Compared with US online respondents who took the English test (${report.norms.collected}, N = ${n}, adults). This historical volunteer sample is not representative of the entire US population.`,`Sammenlignet med amerikanske nettdeltakere (${report.norms.collected}, N = ${n}, voksne). Sammenligningen bygger på den engelske testen; overføring til norsk språk er ikke særskilt validert.`)} <a href="#method">${tr('About the comparison','Om sammenligningen')}</a></p>`;
}
function pctPanel(){
  const pct=!!report.norms;
  return `<div class="d-panel d-pct-panel"><h2 class="d-panel-title">${tr('Your five traits','De fem trekkene dine')}</h2><p class="d-pct-sub">${pct?tr('A higher percentile means more of the trait, not a better result.','Høyere persentil betyr mer av trekket, ikke et bedre resultat.'):tr('Further right means you agreed more with statements about the trait.','Lenger til høyre betyr at du sa deg mer enig i utsagn om trekket.')}</p>${pctInfo()}
    <div class="d-pct-rows"><p class="d-pct-label">${pct?tr('Percentile','Persentil'):tr('Scale 1–5','Skala 1–5')}</p>${sorted().map(d=>`<div class="d-pct-row">${piece(d.code)}<span class="d-pct-name">${esc(name(d))}</span><div class="d-pct-track" role="img" aria-label="${esc(name(d))}: ${esc(scoreText(d))}"><span style="width:${barPos(d)}%;background:${traitColors[d.code]}"></span><i style="left:${barPos(d)}%"></i></div><strong class="d-pct-value">${pct&&hasPct(d)?shownPercentile(d.percentile):Number(d.mean).toFixed(1)}</strong></div>`).join('')}
    <div class="d-pct-row d-pct-axis-row" aria-hidden="true"><span></span><span></span><div class="d-pct-axis"><span>${tr('Lower','Lavere')}</span><span>${tr('Middle','Midten')}</span><span>${tr('Higher','Høyere')}</span></div><span></span></div></div></div>`;
}
function glanceCtx(){const pct=!!report.norms,value=x=>pct&&hasPct(x)?shownPercentile(x.percentile):Number(x.mean).toFixed(1);
  return {domains:sorted(),language,pct,tr,esc,shy,name,scoreText,barPos,value,piece,figureSrc,traitLine:d=>traitLine(d,language),pctInfo:pctInfo(),
    countText:x=>hasPct(x)?tr(`Percentile <span data-count="${value(x)}">${value(x)}</span>`,`<span data-count="${value(x)}">${value(x)}</span>. persentil`):esc(scoreText(x))};}
function nuances(){
  const dist=x=>hasPct(x)?Math.abs(x.percentile-50)/50:Math.abs(x.mean-3)/2;
  const picks=[...sorted()].sort((a,b)=>dist(b)-dist(a)||a.code.localeCompare(b.code)).slice(0,2);
  const card=(d,i)=>{const fs=[...d.facets].sort((a,b)=>dist(b)-dist(a)||a.code.localeCompare(b.code)).slice(0,3);
    return `<article class="d-nuance ${i?'is-cool':'is-warm'}"><div class="d-nuance-top">${piece(d.code)}<h3>${esc(name(d))}</h3><span class="d-nuance-chip">${esc(scoreText(d))}</span></div><p>${esc(traitLine(d,language))}</p>${fs.map(f=>`<div class="d-nuance-row"><span>${esc(f.name)}</span>${miniBar(f,traitColors[d.code])}<strong>${hasPct(f)?shownPercentile(f.percentile):f.mean.toFixed(1)}</strong></div>`).join('')}<p class="d-small">${esc(fs[0].content.description)}</p></article>`;};
  return `<section class="d-nuance-fold"><h2 class="d-nuance-h"><button type="button" class="d-nuance-toggle" aria-expanded="false" aria-controls="nuance-body"><span class="d-nuance-title">${tr('The nuances behind the scores','Nyansene bak skårene')}</span><span class="d-nuance-sub">${tr('Your two most distinctive traits, and the facets that stand out most within them.','De to mest særpregede trekkene dine, og fasettene som skiller seg mest ut i dem.')}</span><span class="d-fcard-plus" aria-hidden="true"></span></button></h2><div class="d-nuance-body" id="nuance-body" role="region" aria-label="${tr('The nuances behind the scores','Nyansene bak skårene')}" hidden><div class="d-nuances">${picks.map(card).join('')}</div></div></section>
    <div class="d-place"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 5c3-1.5 7-1.5 10 1 3-2.5 7-2.5 10-1v14c-3-1.5-7-1.5-10 1-3-2.5-7-2.5-10-1zM12 6v14"/></svg><div><h3>${report.norms?tr('A position, not a verdict','En plassering, ikke en fasit'):tr('A description, not a verdict','En beskrivelse, ikke en fasit')}</h3><p>${report.norms?tr('Small differences need not mean clear differences in your personality. Equal scores are shared in the calculation.','Små forskjeller trenger ikke bety tydelige forskjeller i personligheten din. Like skårer deles likt i beregningen.'):tr('Small differences need not mean clear differences in your personality. Four statements per facet give a starting point, not an exact measurement.','Små forskjeller trenger ikke bety tydelige forskjeller i personligheten din. Fire utsagn per fasett gir et utgangspunkt, ikke en nøyaktig måling.')}</p></div></div>`;
}
const STEPS='five-steps-v1';
function triedSteps(){try{return JSON.parse(sessionStorage.getItem(STEPS)||'[]');}catch{return [];}}
function stepPicks(){
  const picks=[...report.nextSteps];
  if(picks.length>=3)return {picks,explore:false};
  const used=new Set(picks.map(f=>f.code[0]));
  const rest=report.domains.flatMap(d=>d.facets).filter(f=>!picks.some(p=>p.code===f.code)).sort((a,b)=>extremity(b)-extremity(a)||a.code.localeCompare(b.code));
  for(const f of rest){if(picks.length>=3)break;if(!used.has(f.code[0])){picks.push({...f,explore:true});used.add(f.code[0]);}}
  return {picks,explore:report.nextSteps.length===0};
}
function stepsChapter(next){
  const {picks,explore}=stepPicks(),tried=triedSteps();
  const done=picks.filter(f=>tried.includes(f.code)).length;
  const labels=[tr('Start of the week','Starten av uka'),tr('Midweek','Midt i uka'),tr('Weekend','Helgen')];
  return `<section class="d-chapter" id="steps" data-chapter="steps"><p class="eyebrow">05</p>
    <div class="d-steps-hero"><div><h2 class="d-chapter-title">${tr('Your next steps','Dine neste steg')}</h2><p class="d-sub">${tr('Three small experiments for one week. Tick them off as you go, and notice what changes.','Tre små eksperimenter for én uke. Kryss av underveis, og legg merke til hva som endrer seg.')}</p></div>
    <div class="d-steps-progress" role="img" aria-label="${done} / ${picks.length}"><svg viewBox="0 0 36 36"><circle cx="18" cy="18" r="15.5" class="d-ring-bg"/><circle cx="18" cy="18" r="15.5" class="d-ring" stroke-dasharray="${Math.round(97.4*done/Math.max(1,picks.length))} 97.4"/></svg><span><strong>${done}/${picks.length}</strong>${tr('tried','prøvd')}</span></div></div>
    ${explore?`<div class="notice">${tr('Your facet scores are all in the middle range. Instead of inventing three standout tendencies, here are three small explorations from different traits.','Alle fasettskårene dine ligger i midtområdet. Fremfor å finne på tre fremtredende tendenser får du tre små utforskninger fra ulike trekk.')}</div>`:''}
    <ol class="d-journey">${picks.map((f,i)=>`<li class="${f.explore?'d-step is-explore':'step d-step'}${tried.includes(f.code)?' is-done':''}"><div class="d-journey-mark">${piece(f.code[0],'d-journey-piece')}<span>${i+1}</span></div><div class="d-journey-card"><p class="d-step-when">${labels[i]} · ${esc(f.name)} · ${esc(scoreText(f))}</p><h3>${esc(f.content.life)}</h3>${miniBar(f,traitColors[f.code[0]])}<p>${esc(f.interpretation)}</p><label class="d-tried"><input type="checkbox" data-step="${f.code}" ${tried.includes(f.code)?'checked':''}><span>${tr('I tried this','Jeg har prøvd dette')}</span></label></div></li>`).join('')}</ol>
    <div class="d-after"><img class="d-plane" src="assets/design/logo-piece-sky.webp" alt="" aria-hidden="true"><div><h3>${tr('After a week','Etter en uke')}</h3><ul><li>${tr('What happened when you tried it?','Hva skjedde da du prøvde?')}</li><li>${tr('What helped, and what got in the way?','Hva hjalp, og hva sto i veien?')}</li><li>${tr('Which one is worth keeping?','Hvilket er verdt å beholde?')}</li></ul><p class="d-reflect">${esc(reflection(sorted(),language))}</p></div></div>
    <p class="hint">${explore?tr('These explorations use the facets furthest from the midpoint, one from each trait. ','Utforskningene bruker fasettene lengst fra midtpunktet, én fra hvert trekk. '):tr('These steps follow the facets furthest from the midpoint, outside the middle range. ','Stegene følger fasettene lengst fra midtpunktet, utenfor midtområdet. ')}${tr('They are ideas to try, not predictions of what will work.','Dette er ideer å prøve, ikke spådommer om hva som virker.')}</p>
    <p class="hint">IPIP-NEO-120 · ${esc(report.instrumentVersion||'')} · ${esc(report.reportVersion)}${report.norms?` · ${esc(report.norms.version)}`:''} · ${tr('Method and references','Metode og referanser')}: <a href="#method">${tr('Read the evidence and limitations','Les om grunnlaget og begrensningene')}</a></p><p class="hint">Johnson (2014): <a href="https://doi.org/10.1016/j.jrp.2014.05.003">doi.org/10.1016/j.jrp.2014.05.003</a><br>IPIP: <a href="https://ipip.ori.org/newScoringInstructions.htm">ipip.ori.org/newScoringInstructions.htm</a></p>${next}</section>`;
}
function tailorCtx(){return {tr,esc,scoreText,bandShort,language,domains:sorted(),showDev:showRandom()};}
function fullReport(active='overview'){
  const chapters=[['overview',tr('Overview','Oversikt')],['traits',tr('Your five traits','Dine fem trekk')],['work',tr('Work & career','Arbeidsliv og karriere')],['life',tr('Everyday life','Hverdagsliv')],['steps',tr('Your next steps','Dine neste steg')]];
  const all=[...chapters,['reading',tr('How to read your results','Slik leser du resultatene')]];
  if(!all.some(([id])=>id===active))active='overview';
  const nextLink=id=>{const i=all.findIndex(([c])=>c===id),n=all[i+1];return n?`<div class="d-next-chapter"><a class="d-continue" href="#report/${n[0]}"><span>${tr('Continue exploring','Fortsett utforskningen')}<small>${tr('Next','Neste')}: ${n[1]}</small></span><span aria-hidden="true">→</span></a><p class="d-continue-tag">${tr('Small insights. Big possibilities.','Små innsikter. Store muligheter.')}</p></div>`:'';};
  const step=report.nextSteps[0];
  const overview=`<section class="d-chapter" id="overview" data-chapter="overview">
    <p class="eyebrow">${demo?tr('Illustrative profile','Illustrert profil'):tr('Your Big Five report','Din Big Five-rapport')}</p>
    <div class="d-results-hero d-report-hero"><h1>${tr('Personality profile','Personlighetsprofil')}</h1>${profileNameHtml(false)}</div>
    ${glanceHtml(glanceCtx())}${nuances()}${shareBox(true)}
    <h2 class="d-section-title">${tr('Explore your report','Utforsk rapporten din')}</h2>
    <div class="d-explore-cards">
      <article><img src="assets/design/report-work.webp" alt="" aria-hidden="true"><h3>${tr('Work & career','Arbeidsliv og karriere')}</h3><p>${tr('Working style, collaboration and environments to explore.','Arbeidsstil, samarbeid og miljøer å utforske.')}</p><a href="#report/work">${tr('See what it means for you','Se hva det betyr for deg')} <span aria-hidden="true">→</span></a></article>
      <article><img src="assets/design/report-life.webp" alt="" aria-hidden="true"><h3>${tr('Everyday life','Hverdagsliv')}</h3><p>${tr('Social energy, communication and everyday habits.','Sosial energi, kommunikasjon og hverdagsvaner.')}</p><a href="#report/life">${tr('See what it means for you','Se hva det betyr for deg')} <span aria-hidden="true">→</span></a></article>
    </div>
    <div class="d-step-box"><span class="d-report-try-ico">${tryIcon}</span><div><h2>${tr('One small step to try','Ett lite steg å prøve')}</h2><p>${step?esc(step.content.life):tr('Choose one facet that interests you and compare two everyday situations this week.','Velg en fasett du er nysgjerrig på, og sammenlign to hverdagssituasjoner denne uken.')}</p><hr><p class="eyebrow">${tr('Reflect','Reflekter')}</p><p class="d-reflect">${esc(reflection(sorted(),language))}</p></div></div>
    <div class="notice d-disclaimer">${tr('This is a self-reflection tool, not a diagnosis, ability test, or recommendation for a particular job. Results reflect your self-reported answers today.','Dette er et verktøy for selvrefleksjon, ikke en diagnose, evnetest eller anbefaling av et bestemt yrke. Resultatene bygger på dine egne svar i dag.')}</div>
    ${normNote()}${nextLink('overview')}</section>`;
  const traits=`<section class="d-chapter" id="traits" data-chapter="traits"><p class="eyebrow">02</p><h2 class="d-chapter-title d-title-info">${tr('Your five traits','Dine fem trekk')}<button type="button" class="d-info-btn" aria-expanded="false" aria-controls="traits-about" aria-label="${tr('About this chapter','Om dette kapittelet')}" title="${tr('About this chapter','Om dette kapittelet')}"><span class="d-info-i" aria-hidden="true">i</span></button></h2><div class="d-info-pop d-intro-pop" id="traits-about" hidden><p>${esc(content.introduction)}</p><p>${tr('Each broad trait brings together six narrower facets. Four items per facet give a useful starting point, with more uncertainty than the broad scales.','Hvert overordnet trekk samler seks mer avgrensede fasetter. Fire utsagn per fasett gir et nyttig utgangspunkt, med større usikkerhet enn de overordnede skalaene.')}</p></div>${pctInfo()}${traitLogoNav('report',c=>'trait-'+c)}${sorted().map(d=>traitPanel(d,`<section class="trait-chapter d-trait-chapter"><p>${esc(content.domains?.[d.code]?.description||'')}</p><h4 class="d-details-title">${tr('The six facets','De seks fasettene')}</h4><p class="d-details-hint">${tr('Tap + to read more.','Trykk på + for å lese mer.')}</p>${patternHtml(d)}<div class="facet-grid d-fcards">${d.facets.map(facetHtml).join('')}</div>${strengthHtml(d)}${tryHtml(d)}<p>${esc(entry(d).meaning)}</p><div class="d-use"><strong>${tr('Getting the most from it','Slik får du mest ut av det')}</strong><p>${esc(entry(d).watch)}</p></div></section>`)).join('')}${nextLink('traits')}</section>`;
  const context=[['work',tr('Work & career','Arbeidsliv og karriere'),'03','report-work'],['life',tr('Everyday life','Hverdagsliv'),'04','report-life']].map(([id,label,n,img])=>`<section class="d-chapter" id="${id}" data-chapter="${id}"><p class="eyebrow">${n}</p><div class="d-context-head d-context-band"><div>${demo?`<p class="d-demo-pill">${tr('Example profile','Eksempelprofil')}</p>`:''}<h2 class="d-chapter-title">${label}</h2><p class="d-sub">${id==='work'?tr('Use these ideas to explore how you work, rather than to choose a job title.','Bruk ideene til å utforske hvordan du jobber, fremfor å velge en yrkestittel.'):tr('Notice what fits your life, and adapt what you try to the people and situations around you.','Legg merke til hva som passer i livet ditt, og tilpass det du prøver til menneskene og situasjonene rundt deg.')}</p>${id==='work'?careerContextHtml(tailorCtx()):''}</div><img src="assets/design/context/${id}-head.webp" alt="" aria-hidden="true"></div>${id==='work'?careerHtml(tailorCtx()):tailorHtml(id,tailorCtx())}${reportFigureHtml('is-chapter no-print')}<div class="d-ctx-grid" data-ctx="${id}">${sorted().map((d,i)=>contextHtml(d,id,false)).join('')}</div>${nextLink(id)}</section>`).join('');
  const steps=stepsChapter(nextLink('steps'));
  const reading=`<section class="d-chapter" id="reading" data-chapter="reading"><h2 class="d-chapter-title">${tr('How to read this report','Slik leser du rapporten')}</h2><p>${interpretation()}</p><ul class="source-list">${(content.limitations||[]).map(text=>`<li>${esc(text)}</li>`).join('')}</ul></section>`;
  main.innerHTML=`<div class="d-report">
    <aside class="d-contents"><nav aria-label="${tr('Report chapters','Rapportkapitler')}"><p class="eyebrow">${tr('Contents','Innhold')}</p>${chapters.map(([id,label],i)=>`<a href="#report/${id}" ${id===active?'aria-current="page"':''}><span>0${i+1}</span>${label}</a>`).join('')}<hr><a class="d-howto" href="#report/reading" ${active==='reading'?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 5c3-1.5 7-1.5 10 1 3-2.5 7-2.5 10-1v14c-3-1.5-7-1.5-10 1-3-2.5-7-2.5-10-1zM12 6v14"/></svg>${tr('How to read your results','Slik leser du resultatene')}</a></nav></aside>
    <article class="d-report-body report-body"><div class="d-report-toolbar"><a href="#results"><span aria-hidden="true">←</span> ${tr('Your free profile','Gratisprofilen din')}</a><span class="d-toolbar-actions">${!demo?`<button class="text-button" id="report-save">${tr('Save my answers','Lagre svarene mine')}</button>`:''}<button class="d-pdf" id="print"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12M7 10l5 5 5-5M4 19h16"/></svg>${tr('Download PDF','Last ned PDF')}</button></span></div>${notice()}
      ${overview}${traits}${context}${steps}${reading}</article></div>`;
  document.querySelectorAll('.d-chapter').forEach(s=>s.classList.toggle('is-active',s.dataset.chapter===active));
  document.querySelectorAll('[data-step]').forEach(box=>box.addEventListener('change',()=>{const t=new Set(triedSteps());box.checked?t.add(box.dataset.step):t.delete(box.dataset.step);try{sessionStorage.setItem(STEPS,JSON.stringify([...t]));}catch{}fullReport('steps');}));window.onbeforeprint=(()=>document.querySelectorAll('.d-ctx-more').forEach(x=>x.open=true));document.querySelectorAll('.d-ctx-toggle').forEach(btn=>btn.addEventListener('click',()=>{const grid=btn.closest('.d-ctx-grid'),open=btn.getAttribute('aria-expanded')!=='true';grid.querySelectorAll('.d-ctx-toggle').forEach(b=>{const on=open&&b===btn;b.setAttribute('aria-expanded',on);b.closest('.d-ctx-card').classList.toggle('is-open',on);document.getElementById(b.getAttribute('aria-controls')).hidden=!on;});if(open){const panel=document.getElementById(btn.getAttribute('aria-controls')),r=panel.getBoundingClientRect();if(r.bottom>innerHeight)panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});}}));document.querySelectorAll('.d-fcard-toggle').forEach(btn=>btn.addEventListener('click',()=>{const open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',String(open));document.getElementById(btn.getAttribute('aria-controls')).hidden=!open;const card=btn.closest('.d-fcard');card.classList.toggle('is-open',open);if(open&&!matchMedia('(prefers-reduced-motion: reduce)').matches){card.classList.remove('is-filling');card.getBoundingClientRect();card.classList.add('is-filling');card.querySelectorAll('[data-count]').forEach(n=>countUp(n,700));}}));document.querySelector('.d-nuance-toggle')?.addEventListener('click',e=>{const btn=e.currentTarget,open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',String(open));btn.closest('.d-nuance-fold').classList.toggle('is-open',open);document.getElementById('nuance-body').hidden=!open;});initGlance(main,code=>peopleFor(glanceCtx(),code));initTailor(main,tailorCtx());initCareer(main,tailorCtx());initLogoNav(main,{panelId:c=>'trait-'+c});initShare();document.querySelector('#print').onclick=()=>window.print();document.querySelector('#report-save')?.addEventListener('click',downloadAnswers);}
function method(){main.innerHTML=`<article class="page narrow"><p class="eyebrow">${tr('Method & sources','Metode og kilder')}</p><h1>${tr('A model, not a label.','En modell, ikke en merkelapp.')}</h1><p class="lead">${tr('The Big Five describe five broad dimensions of personality. This assessment uses the 120-item IPIP-NEO inventory developed by John A. Johnson.','Big Five beskriver fem overordnede dimensjoner av personlighet. Denne testen bruker John A. Johnsons IPIP-NEO-spørreskjema med 120 utsagn.')}</p><h2>${tr('How scoring works','Slik beregnes skårene')}</h2><p>${tr('Each statement is answered from 1 (Very inaccurate) to 5 (Very accurate). Reverse-keyed items are scored as 6 minus your answer. Four items form each of 30 facets; 24 items form each of the five domains. All 120 answers are required.','Hvert utsagn besvares fra 1 (Svært unøyaktig) til 5 (Svært nøyaktig). Motsatt formulerte utsagn skåres som 6 minus svaret ditt. Fire utsagn inngår i hver av 30 fasetter; 24 utsagn inngår i hvert av fem overordnede trekk. Alle 120 svar kreves.')}</p><p>${interpretation()}</p><p>${norms?tr('The report text follows your percentile: below 30 uses the lower wording, above 70 the higher wording, and the middle wording in between. If the reference data cannot be loaded, means below 2.5 and above 3.5 on the 1–5 scale are used instead. These are editorial ranges, not validated diagnostic cutoffs.','Rapportteksten følger persentilen din: under 30 gir teksten for lavere, over 70 teksten for høyere, og midtteksten mellom disse. Hvis referansedataene ikke kan lastes, brukes gjennomsnitt under 2,5 og over 3,5 på skalaen fra 1 til 5 i stedet. Dette er redaksjonelle områder, ikke validerte diagnostiske grenser.'):tr('For the report text, means below 2.5 use the lower wording, means above 3.5 the higher wording, and the middle wording in between. These are editorial ranges, not validated diagnostic cutoffs.','Rapportteksten bruker teksten for lavere ved gjennomsnitt under 2,5, teksten for høyere over 3,5 og midtteksten mellom disse. Dette er redaksjonelle områder, ikke validerte diagnostiske grenser.')}</p><h2>${tr('Percentiles and the reference group','Persentiler og referansegruppen')}</h2><p>${tr('Percentiles are based on 243,307 complete US online responses from adults with a reported age of 18–90, collected in English in 2001–2011. Participants chose to take the test, and most were young adults. This is a historical reference group, not a representative sample of the US or Norwegian population. Equal scores are shared in the ranking. A percentile describes where a score sits in this group; it is not a percentage of personality, a diagnosis, or a measure of how certain the measurement is. Both languages use the same reference group, and the transfer to Norwegian has not been separately validated. Values that round to 0 or 100 are shown as 1 or 99.','Persentilene bygger på 243 307 komplette amerikanske nettbesvarelser fra voksne med oppgitt alder 18–90, samlet inn på engelsk i 2001–2011. Deltakerne valgte selv å ta testen, og de fleste var unge voksne. Dette er en historisk referansegruppe, ikke et representativt utvalg av hele USAs eller Norges befolkning. Personer med lik skår deles i rangberegningen. En persentil beskriver plasseringen av skåren i denne gruppen; den er ikke en prosentandel av personligheten, en diagnose eller et mål på hvor sikker målingen er. Begge språk bruker samme referansegruppe, og overføringen til norsk er ikke særskilt validert. Verdier som avrundes til 0 eller 100, vises som 1 eller 99.')}</p><p class="hint">${tr('Reference data','Referansedata')}: Kajonius, P. J. &amp; Johnson, J. A. (2019). Supplementary materials. PsychArchives. <a href="https://doi.org/10.23668/psycharchives.2448" target="_blank" rel="noopener">doi:10.23668/psycharchives.2448</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. ${tr('Filtered and aggregated into percentile tables by Fem; the authors have not endorsed this use.','Filtrert og bearbeidet til persentiltabeller av Fem; opphavspersonene har ikke godkjent denne bruken.')} <a href="data/norms-us.json">${tr('Norm table','Normtabell')}</a></p><h2>${tr('Use the results thoughtfully','Bruk resultatene med omtanke')}</h2><p>${tr('This is a self-report snapshot. Mood, interpretation, context, and how you see yourself can affect your answers. Facets contain only four items and should be read with particular care. The assessment does not measure ability, values, mental health, or suitability for a job. Report suggestions are practical reflection prompts, not established personal predictions.','Dette er et øyeblikksbilde basert på egne svar. Humør, tolkning, situasjon og selvbilde kan påvirke svarene. Fasetter inneholder bare fire utsagn og bør leses med særlig varsomhet. Testen måler ikke evner, verdier, psykisk helse eller egnethet for et yrke. Rapportforslagene er praktiske refleksjonsspørsmål, ikke etablerte personlige spådommer.')}</p>${language==='no'?'<div class="notice">Den norske ordlyden kommer fra den MIT-lisensierte oversettelsen kreditert Eli Huseby i bigfive-test-prosjektet. Vi har ikke dokumentert en egen psykometrisk validering eller norsk normering av denne ordlyden. Resultatene egner seg til utforsking og selvrefleksjon.</div>':''}<h2>${tr('Open items, clear attribution','Åpne utsagn, tydelige kilder')}</h2><p>${tr('The IPIP item pool is public domain. The questionnaire itself does not need an MIT license; an implementation may separately use MIT-licensed software. See the project research notes for the pinned item source and license evidence.','IPIPs utsagn er offentlig felleseie (public domain). Selve spørreskjemaet trenger ingen MIT-lisens; en implementasjon kan bruke programvare under MIT-lisens. Se prosjektets forskningsnotater for fast kildeversjon og lisensgrunnlag.')}</p><p>${tr('Some original items ask about political voting and authority. They contribute to the historical Liberalism facet; the report does not infer party affiliation. Intellect does not measure IQ, and Morality does not establish moral worth.','Noen originale utsagn handler om politisk stemmegivning og autoritet. De inngår i den historiske fasetten Liberalisme; rapporten utleder ikke partitilhørighet. Intellekt måler ikke IQ, og Moral fastslår ikke moralsk verdi.')}</p><ul class="source-list"><li><a href="THIRD-PARTY-NOTICES.txt">${tr('Licenses and attribution','Lisenser og kreditering')}</a> · <a href="data/provenance.json">${tr('Instrument provenance','Instrumentets kildehistorikk')}</a></li><li><a href="https://ipip.ori.org/30FacetNEO-PI-RItems.htm" target="_blank" rel="noopener">IPIP: ${tr('facet items and scoring keys','fasettutsagn og skåringsnøkler')}</a></li><li><a href="https://ipip.ori.org/newScoringInstructions.htm" target="_blank" rel="noopener">IPIP: ${tr('scoring instructions','skåringsinstruksjoner')}</a></li><li><a href="https://ipip.ori.org/newPermission.htm" target="_blank" rel="noopener">IPIP: ${tr('public-domain permission','tillatelse til fri bruk')}</a></li><li><a href="https://ipip.ori.org/" target="_blank" rel="noopener">International Personality Item Pool</a></li><li>Johnson, J. A. (2014). Measuring thirty facets of the Five Factor Model with a 120-item public domain inventory: Development of the IPIP-NEO-120. <em>Journal of Research in Personality, 51</em>, 78–89. <a href="https://doi.org/10.1016/j.jrp.2014.05.003" target="_blank" rel="noopener">DOI</a></li></ul>${button(tr('Back to exploring','Tilbake til utforskingen'),report?'#results':'#home',true)}</article>`;}
// Optional account (app/account.js): save the answers and open the profile on any device.
let accountUser=null,accountProfile=null,accountReady=false,accountMsg='',accountBusy=false;
const providerIcon={google:'<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M23.5 12.3c0-.8-.1-1.6-.2-2.3H12v4.5h6.5a5.6 5.6 0 0 1-2.4 3.6v3h3.9c2.2-2.1 3.5-5.1 3.5-8.8z"/><path fill="#34A853" d="M12 24c3.2 0 6-1.1 8-2.9l-3.9-3c-1.1.7-2.5 1.2-4.1 1.2-3.1 0-5.8-2.1-6.7-5H1.3v3.1A12 12 0 0 0 12 24z"/><path fill="#FBBC05" d="M5.3 14.3a7.2 7.2 0 0 1 0-4.6V6.6h-4a12 12 0 0 0 0 10.8z"/><path fill="#EA4335" d="M12 4.8c1.8 0 3.3.6 4.6 1.8l3.4-3.4A12 12 0 0 0 1.3 6.6l4 3.1c.9-2.8 3.6-4.9 6.7-4.9z"/></svg>',apple:'<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M16.4 12.7c0-2.6 2.1-3.8 2.2-3.9-1.2-1.8-3.1-2-3.7-2-1.6-.2-3.1.9-3.9.9-.8 0-2-.9-3.4-.9a5 5 0 0 0-4.2 2.6c-1.8 3.1-.5 7.7 1.3 10.2.8 1.2 1.8 2.6 3.1 2.5 1.3-.1 1.7-.8 3.3-.8s2 .8 3.4.8c1.4 0 2.3-1.3 3.1-2.5a11 11 0 0 0 1.4-2.9 4.5 4.5 0 0 1-2.6-4zM13.9 5.1c.7-.8 1.2-2 1.1-3.1-1 0-2.2.7-3 1.5-.6.7-1.2 1.9-1 3 1.1.1 2.2-.6 2.9-1.4z"/></svg>',x:'<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M17.8 2h3.3l-7.2 8.3L22.4 22h-6.6l-5.2-6.8L4.7 22H1.4l7.7-8.8L1 2h6.8l4.7 6.2zm-1.2 18h1.8L6.6 3.9H4.6z"/></svg>'};
const answersComplete=()=>questions.length===120&&Object.keys(answers).length===120;
async function refreshAccount(){if(!account.enabled()){accountReady=true;return;}try{accountUser=await account.currentUser();accountProfile=accountUser?await account.loadProfile():null;}catch{accountMsg=tr('Could not reach your account right now. Try again in a moment.','Fikk ikke kontakt med kontoen din akkurat nå. Prøv igjen om litt.');}accountReady=true;}
// Sign in without Google: an emailed link (Supabase magic link). Folded away so Google stays the obvious choice.
function emailSignIn(intent,returnTo,off){const google=account.providers().some(p=>p.id==='google');return `<details class="d-signin-email"><summary>${google?tr('Sign in without Google','Logg inn uten Google'):tr('Sign in with email','Logg inn med e-post')}</summary><form data-email-signin data-intent="${intent}" data-return="${returnTo}"><label class="sr-only" for="signin-email-${intent||'x'}">${tr('Email','E-post')}</label><input id="signin-email-${intent||'x'}" type="email" name="email" autocomplete="email" required placeholder="${tr('Your email','E-postadressen din')}"${off?' disabled':''}><button type="submit" class="d-signin-btn"${off?' disabled':''}>${tr('Email me a sign-in link','Send meg en innloggingslenke')}</button><p class="d-signin-email-msg" role="status"></p></form></details>`;}
function signInButtons(intent,returnTo=''){const off=!account.enabled();return `<div class="d-signin">${account.providers().map(p=>{const icon=providerIcon[p.label==='X'?'x':p.id]||'';return `<button type="button" class="d-signin-btn d-signin-${p.label==='X'?'x':p.id}" data-account-action="signin" data-provider="${esc(p.id)}" data-intent="${intent}" data-return="${returnTo}"${off?' disabled':''}>${icon}<span>${tr(`Continue with ${p.label}`,`Fortsett med ${p.label}`)}</span></button>`;}).join('')}${emailSignIn(intent,returnTo,off)}</div>${off?`<p class="d-account-note">${tr('Sign-in is not connected yet. This preview shows how it will look.','Innlogging er ikke koblet til ennå. Forhåndsvisningen viser hvordan det blir.')}</p>`:''}`;}
const savedDate=p=>p?.updatedAt?new Intl.DateTimeFormat(language==='no'?'nb-NO':'en-US',{dateStyle:'long'}).format(new Date(p.updatedAt)):'';
function accountHtml(where){
  const msg=accountMsg?`<p class="d-account-msg" role="status">${esc(accountMsg)}</p>`:'';
  if(!account.enabled()&&!devMode())return where==='page'?`<p>${tr('Sign-in is not available in this preview yet.','Innlogging er ikke tilgjengelig i forhåndsvisningen ennå.')}</p>`:'';
  if(account.enabled()&&!accountReady)return `<p class="d-account-note">${tr('Checking your account …','Sjekker kontoen din …')}</p>`;
  const privacyNote=`<p class="d-account-note">${tr('We store your 120 answers with your account so you can open your profile on any device. You can delete them, or your whole account, at any time.','Vi lagrer de 120 svarene dine på kontoen, så du kan åpne profilen på alle enheter. Du kan slette dem, eller hele kontoen, når som helst.')} <a href="#privacy">${tr('Privacy','Personvern')}</a></p>`;
  if(!accountUser){
    const head=where==='box'?`<div><h2>${tr('Save your profile','Lagre profilen din')}</h2><p>${tr('Sign in to find your profile again later, on any device.','Logg inn for å finne profilen igjen senere, på alle enheter.')}</p></div>`:'';
    return `${head}${signInButtons(where==='box'?'save':'')}${msg}${privacyNote}`;
  }
  const who=`<p class="d-account-who">${tr('Signed in as','Logget inn som')} <b>${esc(accountUser.email||accountUser.name||tr('your account','kontoen din'))}</b></p>`;
  const same=accountProfile&&answersComplete()&&accountProfile.code===profileCode();
  const actions=[];
  if(accountProfile&&!same)actions.push(`<button type="button" class="d-account-primary" data-account-action="open">${tr('Open my saved profile','Åpne den lagrede profilen')}</button>`);
  if(answersComplete()&&!same)actions.push(`<button type="button" class="${accountProfile?'d-account-secondary':'d-account-primary'}" data-account-action="save">${accountProfile?tr('Replace it with the answers in this tab','Erstatt med svarene i denne fanen'):tr('Save this profile','Lagre denne profilen')}</button>`);
  const status=same?`<p class="d-account-saved"><span aria-hidden="true">✓</span> ${tr(`Saved to your account ${savedDate(accountProfile)}.`,`Lagret på kontoen din ${savedDate(accountProfile)}.`)}</p>`:accountProfile?`<p>${tr(`You have a saved profile from ${savedDate(accountProfile)}.`,`Du har en lagret profil fra ${savedDate(accountProfile)}.`)}</p>`:`<p>${tr('No profile is saved yet.','Ingen profil er lagret ennå.')}</p>`;
  const head=where==='box'?`<h2>${tr('Your account','Kontoen din')}</h2>`:'';
  const manage=where==='page'?`<div class="d-account-manage">${accountProfile?`<button type="button" class="text-button" data-account-action="delete-profile">${tr('Delete my saved profile','Slett den lagrede profilen')}</button>`:''}<button type="button" class="text-button" data-account-action="delete-account">${tr('Delete my account','Slett kontoen min')}</button><button type="button" class="text-button" data-account-action="signout">${tr('Sign out','Logg ut')}</button></div>`:`<a class="d-account-link" href="#account">${tr('Manage account','Administrer kontoen')} <span aria-hidden="true">→</span></a>`;
  return `${head}${who}${status}${actions.length?`<div class="d-account-actions">${actions.join('')}</div>`:''}${msg}${manage}`;
}
function paintAccount(){document.querySelectorAll('[data-account]').forEach(el=>{el.innerHTML=accountHtml(el.dataset.account);el.hidden=!el.innerHTML.trim();});}
// Sign-in step between the last question and the loading animation. Required when sign-in is
// connected (Rune 2026-10-16: people must sign in before they see their results); in ?dev=1 previews
// without Supabase it shows with a preview-only way past it.
const askSignIn=()=>account.enabled()?accountReady&&!accountUser:devMode();
// Routes that show the person's own results. With sign-in connected they need an account; the example report (#demo) does not.
const gatedRoute=route=>['loading','results','offer','report','opening'].includes(route)||route.startsWith('report/')||route.startsWith('opening/')||route.startsWith('p=');
const signInGate=route=>account.enabled()&&!demo&&!accountUser&&gatedRoute(route);
function signInStep(){main.innerHTML=`<section class="page narrow d-signin-step"><div class="d-signin-step-brand" aria-hidden="true"><span class="d-signin-step-logo"></span><b>Fem</b></div><p class="d-signin-step-kicker">${tr('Test complete','Testen er fullført')}</p><h1>${tr('Save your profile','Lagre profilen din')}</h1><p class="lead">${tr('Sign in to access your results on any device.','Logg inn for å se resultatene dine på alle enheter.')}</p>${signInButtons('save','loading')}${account.enabled()?'':`<p class="d-signin-optional"><a href="#loading">${tr('Preview only: continue without signing in','Bare forhåndsvisning: fortsett uten å logge inn')}</a></p>`}<a class="d-signin-privacy" href="#privacy">${tr('Privacy','Personvern')}</a></section>`;}
/** The sign-in providers switched on, as words: "Google", "Google or Apple", "Google, Apple or X". */
function signInVia(){const n=account.providers().map(p=>p.label);return n.length<2?n.join(''):`${n.slice(0,-1).join(', ')} ${tr('or','eller')} ${n.at(-1)}`;}
function accountPage(){main.innerHTML=`<article class="page narrow d-account-page"><p class="eyebrow">${tr('My account','Min side')}</p><h1>${tr('Your saved profile','Den lagrede profilen din')}</h1><p class="lead">${tr(`Sign in with ${signInVia()} or by email to keep your profile and open it again on any device.`,`Logg inn med ${signInVia()} eller e-post for å ta vare på profilen og åpne den igjen på alle enheter.`)}</p><section class="d-account-panel" data-account="page" aria-live="polite"></section></article>`;paintAccount();}
async function accountAction(btn){
  if(accountBusy)return;const act=btn.dataset.accountAction;accountMsg='';
  if(act==='delete-account'&&!confirm(tr('Delete your account and your saved profile? This cannot be undone.','Slette kontoen og den lagrede profilen? Dette kan ikke angres.')))return;
  if(act==='delete-profile'&&!confirm(tr('Delete the profile saved on your account?','Slette profilen som er lagret på kontoen?')))return;
  accountBusy=true;btn.disabled=true;
  try{
    if(act==='signin'){await account.signIn(btn.dataset.provider,btn.dataset.return||(location.hash||'#account').slice(1),btn.dataset.intent);return;}
    if(act==='save'){await account.saveProfile(profileCode(),language);accountMsg=tr('Your profile is saved.','Profilen er lagret.');}
    if(act==='open'){const code=accountProfile.code;accountBusy=false;if(openProfileLink(code)&&profileCode()===code){location.hash='results';render();}return;}
    if(act==='delete-profile'){await account.deleteProfile();accountMsg=tr('Your saved profile is deleted.','Den lagrede profilen er slettet.');}
    if(act==='delete-account'){await account.deleteAccount();accountMsg=tr('Your account and saved profile are deleted.','Kontoen og den lagrede profilen er slettet.');}
    if(act==='signout'){await account.signOut();accountMsg=tr('You are signed out.','Du er logget ut.');}
    await refreshAccount();
  }catch{accountMsg=tr('Something went wrong. Nothing was changed. Try again in a moment.','Noe gikk galt, og ingenting ble endret. Prøv igjen om litt.');}
  finally{accountBusy=false;paintAccount();}
}
document.addEventListener('click',event=>{const btn=event.target.closest?.('[data-account-action]');if(btn)accountAction(btn);});
document.addEventListener('submit',async event=>{const form=event.target.closest?.('[data-email-signin]');if(!form)return;event.preventDefault();const msg=form.querySelector('.d-signin-email-msg'),btn=form.querySelector('button'),email=form.elements.email.value;
  if(!account.validEmail(email)){msg.textContent=tr('Check the email address.','Sjekk e-postadressen.');return;}
  btn.disabled=true;msg.textContent='';
  try{await account.signInWithEmail(email,form.dataset.return||(location.hash||'#account').slice(1),form.dataset.intent,answersComplete()?profileCode():'');msg.textContent=tr('Check your email and open the link in this browser.','Sjekk e-posten din og åpne lenken i denne nettleseren.');}
  catch{msg.textContent=tr('Could not send the link. Try again in a moment.','Fikk ikke sendt lenken. Prøv igjen om litt.');}
  finally{btn.disabled=false;}});
async function initAccount(){
  if(!account.enabled()){accountReady=true;return;}
  let back=null;try{back=await account.finishSignIn();}catch{}
  await refreshAccount();
  if(back?.code&&accountUser&&!answersComplete())openProfileLink(back.code);
  if(back?.failed)accountMsg=tr('Sign-in was cancelled or failed. You can try again.','Innloggingen ble avbrutt eller mislyktes. Du kan prøve igjen.')+(back.reason?` (${back.reason})`:'');
  else if(back&&accountUser&&back.intent==='save'&&answersComplete()){try{await account.saveProfile(profileCode(),language);accountProfile=await account.loadProfile();accountMsg=tr('Your profile is saved.','Profilen er lagret.');}catch{accountMsg=tr('Signed in, but the profile could not be saved. Try again.','Du er logget inn, men profilen ble ikke lagret. Prøv igjen.');}}
  if(back||gatedRoute((location.hash||'#home').slice(1))||location.hash==='#signin')render(false);else paintAccount();
}
function privacy(){main.innerHTML=`<article class="page narrow"><p class="eyebrow">${tr('Privacy in this preview','Personvern i forhåndsvisningen')}</p><h1>${tr('Your answers stay here.','Svarene dine blir her.')}</h1><p class="lead">${tr('Scoring and report selection happen in your browser. This app does not send your answers to a server.','Skåring og valg av rapporttekst skjer i nettleseren din. Appen sender ikke svarene dine til en server.')}</p><h2>${tr('Keep your answers for future reports','Behold svarene til senere rapporter')}</h2><p>${tr('Save my answers downloads a file to your device. Restore saved answers reads that file locally and generates the current report from the same responses. You do not need to repeat the test for a report update. The file contains your raw answers; store it privately. Clearing this tab does not delete downloaded files. Send the profile to your email opens your own email app with a link that contains your answers after the # sign; browsers do not send that part to the website.','«Lagre svarene mine» laster ned en fil til enheten din. «Hent lagrede svar» leser filen lokalt og lager gjeldende rapport fra de samme svarene. Du trenger ikke gjenta testen for en rapportoppdatering. Filen inneholder svarene dine; oppbevar den privat. Sletting i fanen sletter ikke nedlastede filer. «Send profilen til e-posten din» åpner ditt eget e-postprogram med en lenke som inneholder svarene etter #-tegnet; nettlesere sender ikke den delen til nettstedet.')}</p>${account.enabled()||devMode()?`<h2>${tr('Signing in','Innlogging')}</h2><p>${tr(`You sign in with ${signInVia()} or with a link sent to your email before you see your results. We store your 120 answers, your language and when you saved them with your account, so you can open your profile on another device. We receive your email address, and your name if you sign in with ${signInVia()}, nothing else. The data is kept in our database provider (Supabase) and is not shared with anyone. Under My account you can delete the saved profile or the whole account at any time.`,`Du logger inn med ${signInVia()} eller med en lenke på e-post før du ser resultatene. Vi lagrer de 120 svarene dine, språket og tidspunktet du lagret, knyttet til kontoen, slik at du kan åpne profilen på en annen enhet. Vi får e-postadressen din, og navnet ditt hvis du logger inn med ${signInVia()}, ikke noe mer. Dataene ligger hos databaseleverandøren vår (Supabase) og deles ikke med noen. Under Min side kan du slette den lagrede profilen eller hele kontoen når som helst.`)}</p>`:''}<h2>${tr('What is stored','Hva som lagres')}</h2><p>${tr('Your answers and current question are saved in session storage in this browser tab, so a refresh does not lose your place. Closing the tab normally clears this storage, although browser restore features may restore it. Use “Clear my answers” below to remove it explicitly. If storage is unavailable, the test still works but a refresh will lose your progress.','Svarene dine og gjeldende spørsmål lagres i sesjonslagring i denne nettleserfanen, slik at fremdriften ikke går tapt hvis siden lastes inn på nytt. Lagringen tømmes vanligvis når fanen lukkes, men nettleserens gjenoppretting kan hente den tilbake. Bruk «Slett svarene mine» nedenfor for å fjerne den selv. Hvis lagring ikke er tilgjengelig, virker testen fortsatt, men fremdriften forsvinner ved oppdatering.')}</p><p>${tr('Your language and country choices are stored separately in local browser storage and remain until you clear site data. The initial suggestion comes from your browser language, not IP geolocation. You can change both at the bottom of every page.','Språk- og landvalg lagres separat i lokal nettleserlagring og beholdes til du sletter nettsteddata. Det første forslaget kommer fra nettleserspråket, ikke IP-basert lokalisering. Du kan endre begge nederst på hver side.')}</p><h2>${account.enabled()?tr('No checkout.','Ingen betaling.'):tr('No account. No checkout.','Ingen konto. Ingen betaling.')}</h2><p>${account.enabled()?tr('Unless you sign in, this preview collects no name or email. It collects no payment information or analytics.','Med mindre du logger inn, samler ikke forhåndsvisningen inn navn eller e-post. Den samler heller ikke inn betalingsinformasjon eller analysedata.'):tr('This preview collects no name, email, payment information, or analytics.','Denne forhåndsvisningen samler ikke inn navn, e-post, betalingsinformasjon eller analysedata.')} ${tr('There is no purchase or recurring charge. The full report is available to explore for free. A saved PDF becomes a file you control; anyone you share it with can read it.','Det finnes ikke noe kjøp eller abonnement. Hele rapporten kan utforskes gratis. En lagret PDF blir en fil du selv kontrollerer; alle du deler den med, kan lese den.')}</p><p>${tr('If you open an external source link, that website applies its own privacy practices. The hosting provider may process ordinary access information, such as IP addresses and request logs. Commercial launch needs published seller/privacy terms and verified payment setup.','Hvis du åpner en ekstern kildelenke, gjelder personvernpraksisen på det nettstedet. Nettleverandøren kan behandle vanlige tilgangsopplysninger, som IP-adresser og forespørselslogger. Kommersiell lansering krever publiserte selger- og personvernvilkår og verifisert betaling.')}</p>${button(tr('Back to exploring','Tilbake til utforskingen'),report?'#results':'#home',true)}</article>`;}
function render(focus=true){if(!questions.length)return;document.querySelector('dialog.d-video-intro')?.close();updateShell();const route=(location.hash||'#home').slice(1);if(signInGate(route)){if(!accountReady){main.innerHTML=`<p class="initial">${tr('Checking your account …','Sjekker kontoen din …')}</p>`;return;}if(route.startsWith('p='))openProfileLink(route.slice(2));if(Object.keys(answers).length===120){location.replace('#signin');return;}location.replace('#test');return;}if(route.startsWith('p=')){openProfileLink(route.slice(2));location.replace('#results');return;}document.body.classList.toggle('in-test',route==='test');const opening=route==='opening'||route.startsWith('opening/');document.body.classList.toggle('in-loading',route==='loading'||opening);if(opening){if(!report){if(Object.keys(answers).length===120)calculate();else{location.hash='test';return;}}openingScreen(route.split('/')[1]);return;}if(route!=='test')shownCairns=null;if(route.startsWith('report/')&&!report&&Object.keys(answers).length===120)calculate();if(route.startsWith('report/')&&!report){location.hash='test';return;}if(route.startsWith('report/')&&report){fullReport(route.split('/')[1]);if(focus){window.scrollTo(0,0);main.focus({preventScroll:true});}return;}if(['results','offer','report'].includes(route)&&!report){if(Object.keys(answers).length===120)calculate();else{location.hash='test';return;}}if(route==='test')assessment();else if(route==='loading'){if(Object.keys(answers).length!==120){location.hash='test';return;}const still=matchMedia('(prefers-reduced-motion: reduce)').matches;const fly=flight;flight=null;main.innerHTML=`<section class="d-loading" role="status"><div class="d-assemble" aria-hidden="true">${['navy','apricot','ivory','steel','sky'].map(c=>`<img class="d-piece d-tri-${c}" src="assets/design/logo-piece-${c}.webp" alt="">`).join('')}</div><h1>${tr('Bringing your profile together.','Vi setter sammen profilen din.')}</h1><p>${tr('Five traits. Your combination.','Fem trekk. Din kombinasjon.')}</p></section>`;const flew=!still&&flyPieces(fly);setTimeout(()=>{if(location.hash==='#loading'){calculate();try{sessionStorage.setItem(INTRO,'1');}catch{}location.hash='results';}},still?1200:flew?3400:4000);}else if(route==='random'){if(showRandom())devRandom(true);else location.replace('#home');return;}else if(route==='rune'){if(showRandom())devRune(true);else location.replace('#home');return;}else if(route==='demo'){calculate(true);location.hash='report';return;}else if(route==='results')results();else if(route==='offer')offer();else if(route==='report')fullReport('overview');else if(route==='method')method();else if(route==='privacy')privacy();else if(route==='account')accountPage();else if(route==='signin'){if(Object.keys(answers).length!==120){location.hash='test';return;}if(accountUser){location.replace('#loading');return;}signInStep();}else home();if(focus){window.scrollTo(0,0);main.focus({preventScroll:true});}}
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();main.focus();});
window.addEventListener('hashchange',()=>render());
// Back from Google: open the page the person signed in from straight away instead of flashing the home page.
{const r=account.enabled()&&account.pendingRoute();if(r)history.replaceState(null,'',`${location.pathname}${location.search}#${r}`);}
load();
let accountWait=0;const accountStart=setInterval(()=>{if(!questions.length&&++accountWait<200)return;clearInterval(accountStart);initAccount();},50);
